8	import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
9	import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
10	import { useSearchTelemetry } from '@/shared/lib/telemetry/useSearchTelemetry';
