40	
41	// Helper function
42	const calculateMovimentada = (item: EventoProduto) => {
43	  if (!item.quantidade_enviada) return 0;
44	  return item.quantidade_enviada - (item.quantidade_retorno || 0);
45	};
46	
47	interface EventoProduto {
48	  id: string;
49	  produto_id: number | null;
50	  produto_nome: string | null;
51	  quantidade: number;
52	  quantidade_enviada: number;
53	  quantidade_retorno: number;
54	  item_separado: boolean;
55	  verificado_retorno: boolean;
56	  unidade: string | null;
57	  observacoes: string | null;
58	}
59	
60	interface Produto {
61	  id: number;
62	  nome: string;
63	  unidade: string | null;
64	}
65	
66	interface Perda {
67	  id: string;
68	  produto_nome: string;
69	  quantidade: number;
70	  motivo: string;
71	  created_at: string;
72	  user_id: string;
73	}
74	
75	export function EventLogistics({ eventoId }: { eventoId: string }) {
76	  const isMobile = useIsMobile();
77	  const [products, setProducts] = useState<EventoProduto[]>([]);
78	  const [loading, setLoading] = useState(true);
79	  const [isAddOpen, setIsAddOpen] = useState(false);
80	  const [searchTerm, setSearchTerm] = useState('');
81	  const [planoLogistica, setPlanoLogistica] = useState('');
82	  const [isEditingPlano, setIsEditingPlano] = useState(false);
83	  const { addLog } = useChangelog(eventoId, 'EVENTO');
84	  const telemetryAttrs = useTelemetryAttrs();
85	  const { trackSearch } = useSearchTelemetry('evento_logistica');
86	
87	  const [perdas, setPerdas] = useState<Perda[]>([]);
88	  const [isAddingLoss, setIsAddingLoss] = useState(false);
89	  const [lossForm, setLossForm] = useState({
90	    produto_nome: '',
91	    quantidade: '',
92	    motivo: '',
93	  });
94	
95	  // Budget Generator State
96	  const [isBudgetOpen, setIsBudgetOpen] = useState(false);
97	  const [budgetForm, setBudgetForm] = useState({
98	    clientName: '',
99	    address: '',
100	    items: [] as { id: number; name: string; price: number; qty: number }[],
